CREATE TABLE public.chat_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plant_owner_id uuid NOT NULL, title text NOT NULL DEFAULT 'New conversation', record_id uuid REFERENCES public.paper_records(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_threads TO authenticated;
GRANT ALL ON public.chat_threads TO service_role;
ALTER TABLE public.chat_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_threads ON public.chat_threads TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.plant_owner_id = chat_threads.plant_owner_id)) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.plant_owner_id = chat_threads.plant_owner_id));
CREATE TABLE public.chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.chat_threads(id) ON DELETE CASCADE, sdk_id text NOT NULL, role text NOT NULL CHECK (role IN ('user','assistant')), parts jsonb NOT NULL DEFAULT '[]', completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id, sdk_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_messages TO authenticated;
GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_messages ON public.chat_messages TO authenticated USING (EXISTS (SELECT 1 FROM public.chat_threads t WHERE t.id = chat_messages.thread_id)) WITH CHECK (EXISTS (SELECT 1 FROM public.chat_threads t WHERE t.id = chat_messages.thread_id));
CREATE INDEX chat_messages_thread_time ON public.chat_messages(thread_id,created_at);
CREATE TABLE public.savings_settings (plant_owner_id uuid PRIMARY KEY, paperwork_minutes numeric NOT NULL DEFAULT 5 CHECK (paperwork_minutes BETWEEN 0 AND 480), ai_minutes numeric NOT NULL DEFAULT 10 CHECK (ai_minutes BETWEEN 0 AND 480), hourly_cost numeric NOT NULL DEFAULT 25 CHECK (hourly_cost BETWEEN 0 AND 10000), monthly_service_cost numeric NOT NULL DEFAULT 0 CHECK (monthly_service_cost BETWEEN 0 AND 100000), currency text NOT NULL DEFAULT 'EUR' CHECK (currency IN ('EUR','USD','GBP','RSD')), tracking_started_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.savings_settings TO authenticated;
GRANT ALL ON public.savings_settings TO service_role;
ALTER TABLE public.savings_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_plant_settings ON public.savings_settings FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.plant_owner_id = savings_settings.plant_owner_id));
CREATE POLICY managers_insert_settings ON public.savings_settings FOR INSERT TO authenticated WITH CHECK (public.is_plant_manager(plant_owner_id));
CREATE POLICY managers_update_settings ON public.savings_settings FOR UPDATE TO authenticated USING (public.is_plant_manager(plant_owner_id)) WITH CHECK (public.is_plant_manager(plant_owner_id));
CREATE TABLE public.savings_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plant_owner_id uuid NOT NULL, actor_id uuid NOT NULL, machine_id uuid, kind text NOT NULL CHECK (kind IN ('paperwork','ai_answer')), source_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,source_id));
GRANT SELECT ON public.savings_activity TO authenticated;
GRANT ALL ON public.savings_activity TO service_role;
ALTER TABLE public.savings_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_scoped_activity ON public.savings_activity FOR SELECT TO authenticated USING (public.is_plant_manager(plant_owner_id) OR (actor_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.plant_owner_id = savings_activity.plant_owner_id) AND (machine_id IS NULL OR public.can_read_machine(machine_id,plant_owner_id))));
CREATE FUNCTION public.track_afs_paperwork() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.savings_activity(plant_owner_id,actor_id,machine_id,kind,source_id) VALUES(NEW.owner_id,auth.uid(),NEW.machine_id,'paperwork',NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER track_afs_paperwork AFTER INSERT ON public.paper_records FOR EACH ROW EXECUTE FUNCTION public.track_afs_paperwork();
CREATE FUNCTION public.track_afs_chat() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.role = 'assistant' AND NEW.completed AND (TG_OP = 'INSERT' OR NOT OLD.completed) THEN INSERT INTO public.savings_activity(plant_owner_id,actor_id,kind,source_id) SELECT t.plant_owner_id,t.user_id,'ai_answer',NEW.id FROM public.chat_threads t WHERE t.id = NEW.thread_id ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER track_afs_chat AFTER INSERT OR UPDATE ON public.chat_messages FOR EACH ROW EXECUTE FUNCTION public.track_afs_chat();
CREATE TABLE public.ai_access_blocks (user_id uuid PRIMARY KEY, reason text NOT NULL, status integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_access_blocks TO service_role;
ALTER TABLE public.ai_access_blocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON FUNCTION public.track_afs_paperwork() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.track_afs_chat() FROM PUBLIC;